#!/usr/bin/env bash
# One-off: creates the 1Password item for apps/gitea-runner in the Kubernetes
# vault. The registration token is an instance-wide runner token generated by
# Gitea itself; it is piped straight into 1Password and never printed.
set -euo pipefail

eval "$(op signin)"

TOKEN=$(kubectl -n gitea exec deploy/gitea -c gitea -- gitea actions generate-runner-token)

op item create --vault Kubernetes --category password --title gitea-runner \
  "GITEA_RUNNER_REGISTRATION_TOKEN[password]=$TOKEN" >/dev/null
echo "created: gitea-runner"
